package com.trainflow.document;
import static org.junit.jupiter.api.Assertions.*; import java.nio.file.*; import java.util.UUID; import org.junit.jupiter.api.*;
class DocumentStorageTest {Path root;DocumentStorage storage;@BeforeEach void setup()throws Exception{root=Files.createTempDirectory("trainflow-docs");storage=new DocumentStorage(root.toString(),1);}@AfterEach void cleanup()throws Exception{try(var paths=Files.walk(root)){paths.sorted(java.util.Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}@Test void storesAtomicallyAndComputesHash()throws Exception{var value=storage.store(UUID.randomUUID(),DocumentType.PROGRAM,"%PDF-test".getBytes());assertTrue(storage.resolve(value.relativePath()).toFile().isFile());assertEquals(64,value.sha256().length());}@Test void rejectsTraversal(){assertThrows(IllegalArgumentException.class,()->storage.resolve("../secret.pdf"));assertThrows(IllegalArgumentException.class,()->storage.resolve("/secret.pdf"));}}
